-- P1#5 Task 1: ChatBI 评测 SQLite fixture（六表 DDL + 种子数据）
-- 表/列与 SIX_TABLE_MODELS 对齐（test_chatbi_evalset.py:48-112）。
-- 纪律:每条 evalset expected_sql 结果非空且同题型不同用例可区分。
-- DATE 用 'YYYY-MM-DD' 字符串（SQLite 兼容，PoC 已验证）。

CREATE TABLE employee (
    id        INTEGER PRIMARY KEY,
    name      TEXT,
    dept_id   INTEGER,
    hire_date TEXT,
    email     TEXT
);

CREATE TABLE department (
    id   INTEGER PRIMARY KEY,
    name TEXT
);

CREATE TABLE salary (
    id        INTEGER PRIMARY KEY,
    emp_id    INTEGER,
    amount    REAL,
    pay_month TEXT
);

CREATE TABLE customer (
    id       INTEGER PRIMARY KEY,
    name     TEXT,
    phone    TEXT,
    owner_id INTEGER,
    region   TEXT
);

CREATE TABLE product (
    id       INTEGER PRIMARY KEY,
    name     TEXT,
    category TEXT,
    price    REAL
);

CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    order_no    TEXT,
    customer_id INTEGER,
    product_id  INTEGER,
    amount      REAL,
    quantity    INTEGER,
    created_at  TEXT
);

-- department: 4 行

-- employee: 12 行跨 4 部门，hire_date 跨 2025-2026 各季

-- salary: 24 行（12 员工 × 2 月：2025-11 / 2025-12），金额分层 5k-30k

-- customer: 8 行（id 1001-1008 与旧用例 e004 口径对齐；4 区域各 2，
-- 负责人覆盖多员工——张伟 1001 / 王强 1003 / 陈杰 1005 / 郑浩 1011）

-- product: 8 行（4 类别各 2），价 50-2000

-- orders: 30 行（跨 8 客户/8 产品/月份 2025-10 至 2026-09，金额确定可区分）
